"""Writes crates/rst/src/tables.rs: the character classes and URI schemes
docutils' inline markup rules use, and the character widths its tables
and titles use, taken from docutils and Python (`re`, `unicodedata`) so
lsdocs-rst classifies characters exactly as docutils does.

Run through `nur gen rst`, which pins the docutils version.
"""

import re
import sys
import unicodedata
from pathlib import Path

import docutils
from docutils.utils import punctuation_chars as pc
from docutils.utils import urischemes

HEADER = """\
//! Character tables, generated by `scripts/rst-tables.py` (`nur gen rst`)
//! from docutils {version} and Python's `re` and `unicodedata`. Do not edit.
//!
//! Each table is a sorted list of inclusive code point ranges.

"""


def ranges(pattern: str) -> list[tuple[int, int]]:
    rx = re.compile(pattern)
    return predicate_ranges(lambda c: rx.fullmatch(c) is not None)


def predicate_ranges(test) -> list[tuple[int, int]]:
    out: list[list[int]] = []
    for cp in range(sys.maxunicode + 1):
        if 0xD800 <= cp <= 0xDFFF:
            continue
        if test(chr(cp)):
            if out and out[-1][1] == cp - 1:
                out[-1][1] = cp
            else:
                out.append([cp, cp])
    return [(a, b) for a, b in out]


def table(name: str, doc: str, pattern: str) -> str:
    return render(name, doc, ranges(pattern))


def ranges_table(name: str, doc: str, test) -> str:
    return render(name, doc, predicate_ranges(test))


def render(name: str, doc: str, items: list[tuple[int, int]]) -> str:
    body = "".join(f"    (0x{a:04X}, 0x{b:04X}),\n" for a, b in items)
    return f"/// {doc}\npub(crate) const {name}: &[(u32, u32)] = &[\n{body}];\n\n"


def chars(name: str, doc: str, text: str) -> str:
    body = "".join(f"    '\\u{{{ord(c):x}}}',\n" for c in text)
    return f"/// {doc}\npub(crate) const {name}: &[char] = &[\n{body}];\n\n"


def main(out: Path) -> None:
    code = HEADER.format(version=docutils.__version__)
    code += table(
        "START_PRECEDING",
        "What may precede an inline markup start-string: whitespace, openers, delimiters.",
        r"\s|[%s%s]" % (pc.openers, pc.delimiters),
    )
    code += table(
        "END_FOLLOWING",
        "What may follow an inline markup end-string: whitespace, escapes, closing delimiters, delimiters, closers.",
        "\\s|[\x00%s%s%s]" % (pc.closing_delimiters, pc.delimiters, pc.closers),
    )
    code += table("WHITESPACE", "Python's `\\s`.", r"\s")
    code += ranges_table(
        "WIDE",
        "East Asian Wide and Fullwidth characters (two columns).",
        lambda c: unicodedata.east_asian_width(c) in "WF",
    )
    code += ranges_table(
        "COMBINING",
        "Combining characters (no columns; Python's `unicodedata.combining`).",
        lambda c: unicodedata.combining(c) != 0,
    )
    code += table("WORD", "Python's `\\w`.", r"\w")
    code += chars("OPENERS", "docutils' `openers`, index-aligned with `CLOSERS`.", pc.openers)
    code += chars("CLOSERS", "docutils' `closers`.", pc.closers)
    pairs = "".join(
        f"    ('\\u{{{ord(k):x}}}', \"{''.join(f'\\u{{{ord(c):x}}}' for c in v)}\"),\n"
        for k, v in sorted(pc.quote_pairs.items())
    )
    code += (
        "/// Additional open and close quote pairs (docutils' `quote_pairs`).\n"
        f"pub(crate) const QUOTE_PAIRS: &[(char, &str)] = &[\n{pairs}];\n\n"
    )
    schemes = "".join(f'    "{s}",\n' for s in sorted(urischemes.schemes))
    code += (
        "/// The URI schemes docutils recognizes in standalone URIs, sorted.\n"
        f"pub(crate) const URI_SCHEMES: &[&str] = &[\n{schemes}];\n"
    )
    out.write_bytes(code.encode())
    print(f"docutils {docutils.__version__}: wrote {out}")


if __name__ == "__main__":
    main(Path(sys.argv[1]))
